questions.solutionCode:
function solve(tokenAddress, minAmount) {
  const query = `query($token: String!, $minAmount: String!) {
    transfers(where: { token: $token, amount_gte: $minAmount }) {
      id
      from
      to
      amount
      timestamp
    }
  }`;
  return JSON.stringify({ query, variables: { token: tokenAddress, minAmount } });
}
